    let left = 0, right = n - 1, result = -1;
    while (left <= right) {
        const mid = Math.floor((left + right) / 2);
        if (arr[mid] > target)
            right = mid - 1;
        else if (arr[mid] < target)
            left = mid + 1;
        else {
            result = mid;      // Record the found index
            right = mid - 1;   // Continue searching left for an earlier occurrence
